import './DataTable.css';

export type Row = Record<string, string>;

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const PLACEHOLDER_ROW_COUNT = 5;
const SHIMMER_CELL_COUNT = 3;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns =
    rows.length > 0 ? Object.keys(rows[0]) : Array.from({ length: SHIMMER_CELL_COUNT }, (_, i) => `col-${i}`);

  return (
    <table role="table" className="data-table">
      <thead>
        <tr role="row">
          {columns.map((col) => (
            <th key={col} role="columnheader" className="data-table-header-cell" scope="col">
              {col}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {loading
          ? Array.from({ length: PLACEHOLDER_ROW_COUNT }, (_, rowIndex) => (
              <tr key={rowIndex} role="row" className="data-table-row">
                {Array.from({ length: SHIMMER_CELL_COUNT }, (_, cellIndex) => (
                  <td key={cellIndex} role="cell" className="data-table-shimmer-cell">
                    <div className="data-table-shimmer-block" />
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row, rowIndex) => (
              <tr key={rowIndex} role="row" className="data-table-row">
                {columns.map((col) => (
                  <td key={col} role="cell" className="data-table-cell">
                    {row[col]}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}
